// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let NUMBER = 200;
let cnt;

let circles = new Array(NUMBER);

let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

class MyCircle {
  constructor(px, py, nx, ny, radius, step, theta, times) {
    this.px = px;
    this.py = py;
    this.nx = nx;
    this.ny = ny;
    this.r = radius;
    this.step = step;
    this.theta = theta;
    this.times = times;
  }

  draw() {
    fill(220);
    var cd = getColor();
    stroke(cd);
    angleMode(DEGREES);

    var ra, nx, ny;
    var st = this.step;
    var th = this.theta;
    var gx = this.px;
    var gy = this.py;
    var dr = random() > 0.5 ? 1.0 : -1.0;

    var b = 3;
    if(gy > h/2) {
      b = -3;
    }


    for(let k = 0; k < this.times; k++) {

      ra = map(k, 0, this.times, 1, this.r);

      push();
      translate(gx, gy);
      rotate(th*k);

      for(let i = 0; i < this.ny; i++) {
        var ky = gy + i * st * dr - k*b;
        for(let j = 0; j < this.nx; j++) {
          var kx = gx + j * st * dr;
          circle(kx, ky, ra); 
          circle(kx, ky, ra*0.7); 
          circle(kx, ky, ra*0.4); 
        }      
      }

      pop();
    }
  }
}

function build() {
  for (let i = 0; i < NUMBER; i++) {
    var px = s * int(random(50));
    var py = s * int(random(50));
    var nx = int( random(2, 8) );
    var ny = int( random(2, 8) );

    var rd, st, ti, th;
    if(random() < 0.95) {
      rd = random(15, 25);
      st = rd*random(0.4, 1.2);
      ti = int(random(5,15));
      th = random(-1, 1); 
    } else {
      rd = random(15, 45);
      st = rd*random(0.4, 1.2);
      ti = int(random(10,30));
      th = random(-4, 4);
    }
    circles[i] = new MyCircle(px, py, nx, ny, rd, st, th, ti);
  }  
}


function mousePressed() {
  build();
  redraw();
}

function setup() {
  createCanvas(w, h);
  pixelDensity(2);

  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);

  build();
  cnt = 0;
}


function draw() {
  background(220);
  strokeWeight(1);

  for (let i = 0; i < NUMBER; i++) {
      circles[i].draw();
    }    

  drawGrids();
  drawFrame();
}


// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor(x, y) {
  var l = pal.length;
  var k = 1000;
  var cc = noise(x/k, y/k);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

function getColor() {
  var l = pal.length;
  var cc = random();

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

